#nullable enable
using Wolverine.Http;
using Wolverine.Marten;
using Drafting.Contracts;

namespace Drafting.Slices.Drafting;

/// <summary>
/// The CREATE slice, and deliberately NOT an aggregate handler.
///
/// <c>[WriteAggregate]</c> fetches an existing stream and folds it. There is nothing to fetch here: the id is
/// minted in this method, so the stream cannot exist yet, and asking for it would be asking for the thing
/// this slice is about to make. <c>MartenOps.StartStream</c> says that plainly.
///
/// Worth stating because it marks the boundary of the workflow: **the aggregate handler workflow is for
/// changing state, not for creating it.** Every slice in this model is a Command slice, and only one of them
/// can use it.
/// </summary>
public static class DraftEmailEndpoint
{
    public const string Route = "/emails";

    [WolverinePost(Route), EmptyResponse]
    public static (EmailDrafted, IStartStream) Draft(DraftEmail command)
    {
        // terminal="emailId:generated" and terminal="draftedAt:clock" — both supplied by the handler, which
        // is what the model records by marking them terminal rather than leaving them unsourced.
        var emailId = command.EmailId == Guid.Empty ? Guid.NewGuid() : command.EmailId;

        var drafted = new EmailDrafted(
            emailId, command.To, command.Subject, command.Body, DateTimeOffset.UtcNow);

        return (drafted, MartenOps.StartStream<ReviseSubjectState>(emailId, drafted));
    }
}
